function renewal_ok($v,$why){if(!$v)throw new RuntimeException($why);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);stock_query($db,"INSERT INTO users(name,email,password_hash,role) VALUES('Fixture','renewal@example.invalid','unused','usuario')");stock_query($db,"INSERT INTO pro_subscriptions(reference,user_id,provider_id,status,amount_cents) VALUES('renewal-ref',1,'renewal-sub','authorized',10000)");$payments=['1'=>'approved','2'=>'approved'];$config=['enabled'=>true,'seller'=>'123','buyer'=>'test_user_fixture@testuser.com','amount'=>10000,'url'=>'https://repotools-desarrollo.onrender.com','plan'=>'renewal-plan'];
$service=new ProSubscriptions($db,$config,function($method,$path)use(&$payments){if($path==='/preapproval/renewal-sub')return ['id'=>'renewal-sub','external_reference'=>'renewal-ref','preapproval_plan_id'=>'renewal-plan','collector_id'=>123,'status'=>'authorized','auto_recurring'=>['frequency'=>1,'frequency_type'=>'months','currency_id'=>'ARS','transaction_amount'=>100]];if(preg_match('~^/authorized_payments/invoice-([12])$~',$path,$m))return ['id'=>'invoice-'.$m[1],'preapproval_id'=>'renewal-sub','debit_date'=>$m[1]==='1'?'2030-01-31T10:00:00Z':'2030-02-28T10:00:00Z','payment'=>['id'=>$m[1]]];if(preg_match('~^/v1/payments/([12])$~',$path,$m))return ['id'=>$m[1],'status'=>$payments[$m[1]],'live_mode'=>false,'collector_id'=>123,'currency_id'=>'ARS','transaction_amount'=>100];throw new RuntimeException('Unexpected request');});
$until=fn()=>(int)$db->query('SELECT paid_until FROM pro_subscriptions')->fetchColumn();$service->invoice('invoice-1');renewal_ok($until()===strtotime('2030-02-28T10:00:00Z'),'Calendar first period');$service->invoice('invoice-2');$renewed=$until();renewal_ok($renewed===strtotime('2030-03-28T10:00:00Z'),'Next approved invoice renews paid period');$service->invoice('invoice-2');renewal_ok($until()===$renewed,'Repeated renewal does not extend twice');$payments['2']='rejected';$service->invoice('invoice-2');renewal_ok($until()===strtotime('2030-02-28T10:00:00Z'),'Rejected renewal preserves previous paid invoice');$payments['2']='approved';$service->invoice('invoice-2');$service->invoice('invoice-1');renewal_ok($until()===$renewed,'Out of order invoice cannot shorten renewal');$payments['2']='refunded';$service->invoice('invoice-2');renewal_ok($until()===strtotime('2030-02-28T10:00:00Z'),'Refund removes only renewed period');echo "OK renewal: calendar boundaries, duplicate, rejection, out-of-order and refund. Simulated provider only.\n";
